// Public Domain under http://unlicense.org, see link for details.

// Hermite interpolation (similar to Catmull-Rom) at border,
// where some data is unavailable.

// A brief recap.
// Hermite spline takes some values and derivatives at endpoints,
// and constructs a (lowest order) polynomial that matches them all.
// Catmull-Rom is a cubic Hermite spline with derivatives computed
// as central finite differencs (with 4-tap stencil of Catmull-Rom,
// we can actually compute finite differences differently, but that
// would make them mismatch between neighbouring splines).
// With one point removed, we can still do that, except use 3-taps
// forward difference for our border point. The result turns out
// to be simply quadratic polynomial fitted through 3 extant points.
// This is also equivalent to constructing a virtual point
//     A' = D-3*(C-B)
// and using that with ordinary Catmull-Rom spline.

// All of this is probably well-known.

// See also:
// https://en.wikipedia.org/wiki/Cubic_Hermite_spline#Catmull%E2%80%93Rom_spline
// https://en.wikipedia.org/wiki/Finite_difference_coefficient
// "Mitchell-Netravali <-> Bezier", https://www.shadertoy.com/view/DlycD3
// "Quintic Hermite spline",        https://www.shadertoy.com/view/XflXz7
// "Hermite spline kernels",        https://www.shadertoy.com/view/McfXWs

#define Type float // we are interpolating floats in this example, but it can be whatever.

// Catmull-Rom spline.
// Weight matrix.
// [ [  0 ,  1 ,  0 ,  0],
//   [−1/2,  0 , 1/2,  0],
//   [  1 ,−5/2,  2 ,−1/2],
//   [−1/2, 3/2,−3/2, 1/2]]
//
//     A     B     C     D
//           <--t-->
Type cubic_hermite_4taps_center(Type A,Type B,Type C,Type D,float t)
{
    vec4 w=vec4(1,t,t*t,t*t*t)*transpose(mat4( // NOTE: GLSL matrices are column-major.
         0.0, 1.0, 0.0, 0.0,
        -0.5, 0.0, 0.5, 0.0,
         1.0,-2.5, 2.0,-0.5,
        -0.5, 1.5,-1.5, 0.5));
    return w[0]*A+w[1]*B+w[2]*C+w[3]*D;
}

// Hermite spline at border.
// Weight matrix.
// [ [  1 , 0,  0 ],
//   [−3/2, 2,−1/2],
//   [ 1/2,−1, 1/2]]
//
//     B     C     D
//     <--t-->
Type quadratic_hermite_3taps_left(Type B,Type C,Type D,float t)
{
    vec3 w=vec3(1,t,t*t)*transpose(mat3( // NOTE: GLSL matrices are column-major.
         1.0, 0.0, 0.0,
        -1.5, 2.0,-0.5,
         0.5,-1.0, 0.5));
    return w[0]*B+w[1]*C+w[2]*D;
}

// NOTE: right-side border is simply
// quadratic_hermite_3taps_left(C,B,A,1.0-t)

void mainImage(out vec4 fragColor,in vec2 fragCoord)
{
    vec2 xy=(2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec3 col=vec3(0.02);
    Type A=sin(0.11*iTime);
    Type B=sin(0.13*iTime);
    Type C=sin(0.17*iTime);
    Type D=sin(0.19*iTime);
    Type Aprime=D-3.0*(C-B);
    float x=0.5+1.5*xy.x;
    float y=1.5*xy.y;
    col+=0.008*float(x>0.0);
    col=mix(col,0.1*vec3(0.7,0.6,0.5),smoothstep(0.1+length(fwidth(vec2(x,y))),0.1,distance(vec2(x,y),vec2(-1,A))));
    col=mix(col,0.8*vec3(0.7,0.6,0.5),smoothstep(0.1+length(fwidth(vec2(x,y))),0.1,distance(vec2(x,y),vec2( 0,B))));
    col=mix(col,0.8*vec3(0.7,0.6,0.5),smoothstep(0.1+length(fwidth(vec2(x,y))),0.1,distance(vec2(x,y),vec2( 1,C))));
    col=mix(col,0.4*vec3(0.7,0.6,0.5),smoothstep(0.1+length(fwidth(vec2(x,y))),0.1,distance(vec2(x,y),vec2( 2,D))));
    col=mix(col,0.1*vec3(0.4,0.4,0.7),smoothstep(0.1+length(fwidth(vec2(x,y))),0.1,distance(vec2(x,y),vec2(-1,Aprime))));
    float v3=cubic_hermite_4taps_center(A,B,C,D,x);
    float v2=quadratic_hermite_3taps_left(B,C,D,x);
    col=mix(col,(-0.5+0.7*float(x>0.0)+0.7*float(x<1.0))*vec3(0.1,0.7,0.1),smoothstep(1.5*fwidth(v3-y),0.0,abs(v3-y)));
    col=mix(col,(-0.5+0.8*float(x>0.0)+0.6*float(x<1.0))*vec3(0.7,0.1,0.1),smoothstep(1.5*fwidth(v2-y),0.0,abs(v2-y)));
    float e3=cubic_hermite_4taps_center(Aprime,B,C,D,x);
    if(fract(8.0*x)>0.5)
    col=mix(col,(-0.5+0.7*float(x>0.0)+0.7*float(x<1.0))*vec3(0.1,0.1,0.7),smoothstep(1.5*fwidth(e3-y),0.0,abs(e3-y)));
    col=mix(12.92*col,1.055*pow(col,vec3(1.0/2.4))-0.055,step(0.0031308,col)); // sRGB
    fragColor=vec4(col,1.0);
}
